// --- Physics (movement + wall/paddle bounces) ------------------------------

// Face of a ball/brick overlap, by least penetration. Equal penetrations
// (corner) are reported as 'corner': both axes are then flipped.
function overlapFace(ball, brick) {
  const penX = Math.min(ball.x + ball.r, brick.x + brick.w) - Math.max(ball.x - ball.r, brick.x);
  const penY = Math.min(ball.y + ball.r, brick.y + brick.h) - Math.max(ball.y - ball.r, brick.y);
  if (Math.abs(penX - penY) < 1e-6) return 'corner';
  if (penX < penY) return ball.x < brick.x ? 'left' : 'right';
  return ball.y < brick.y ? 'top' : 'bottom';
}

// Bounces the ball off one overlapping brick: flips the velocity component of
// the face hit (both on a corner) and pushes the ball out of the rectangle.
function bounceBall(ball, brick) {
  const face = overlapFace(ball, brick);
  if (face === 'corner') {
    if (ball.x < brick.x) ball.x = brick.x - ball.r;
    else if (ball.x > brick.x + brick.w) ball.x = brick.x + brick.w + ball.r;
    if (ball.y < brick.y) ball.y = brick.y - ball.r;
    else if (ball.y > brick.y + brick.h) ball.y = brick.y + brick.h + ball.r;
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
    return;
  }
  if (face === 'left') { ball.x = brick.x - ball.r; ball.vx = -Math.abs(ball.vx); }
  else if (face === 'right') { ball.x = brick.x + brick.w + ball.r; ball.vx = Math.abs(ball.vx); }
  else if (face === 'top') { ball.y = brick.y - ball.r; ball.vy = -Math.abs(ball.vy); }
  else { ball.y = brick.y + brick.h + ball.r; ball.vy = Math.abs(ball.vy); }
}
```

