// Swept AABB test (slab method): does the ball's path segment from (x0,y0) to
// (x1,y1) cross the brick grown by `r`? Returns null, or { t, face } with
// t ∈ [0, 1]. t === 0 means the segment starts inside the grown box: the
// caller falls back to the positional test.
function sweptBrickHit(x0, y0, x1, y1, brick, r) {
  const dx = x1 - x0;
  const dy = y1 - y0;
  const xl = brick.x - r;
  const xh = brick.x + brick.w + r;
  const yl = brick.y - r;
  const yh = brick.y + brick.h + r;

  let tx0, tx1;
  if (Math.abs(dx) < 1e-12) {
    if (x0 < xl || x0 > xh) return null;
    tx0 = -Infinity;
    tx1 = Infinity;
  } else {
    tx0 = (xl - x0) / dx;
    tx1 = (xh - x0) / dx;
    if (tx0 > tx1) { const t = tx0; tx0 = tx1; tx1 = t; }
  }

  let ty0, ty1;
  if (Math.abs(dy) < 1e-12) {
    if (y0 < yl || y0 > yh) return null;
    ty0 = -Infinity;
    ty1 = Infinity;
  } else {
    ty0 = (yl - y0) / dy;
    ty1 = (yh - y0) / dy;
    if (ty0 > ty1) { const t = ty0; ty0 = ty1; ty1 = t; }
  }

  const tClose = Math.max(tx0, ty0);
  const tFar = Math.min(tx1, ty1);
  if (tClose > tFar || tFar < 0 || tClose > 1) return null;
  if (tClose <= 0) return { t: 0, face: null };

  const corner =
    tx0 !== -Infinity && ty0 !== -Infinity && Math.abs(tx0 - ty0) < 1e-9;
  let face;
  if (corner) face = 'corner';
  else if (tx0 > ty0) face = dx > 0 ? 'left' : 'right';
  else face = dy > 0 ? 'top' : 'bottom';
  return { t: tClose, face };
}
```

