```js
// --- Physics (movement + wall/paddle/brick bounces) ------------------------

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the paddle and the bricks. Bricks are resolved with one swept
// pass per step: the ball bounces at most once, off the earliest face, and
// every brick reached at that time is destroyed and scored.
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;
  const prevX = ball.x;
  const prevY = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle: swept test against the paddle grown by the ball radius, so a fast
  // ball cannot cross the paddle between two frames. The ball always exits
  // through the top of the paddle.
  if (ball.vy > 0) {
    const s = sweptBrickHit(prevX, prevY, ball.x, ball.y, paddle, ball.r);
    if (s && s.t <= 1) {
      ball.y = paddle.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
      // The rebound angle depends on where the paddle was hit. The dead zone
      // at the exact center is absorbed so the ball never goes straight up.
      let hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
      if (Math.abs(hit) < 0.1) hit = hit >= 0 ? 0.1 : -0.1;
      ball.vx = ballSpeed(state.level) * 0.6 * hit;
      // Renormalize: a paddle bounce keeps exactly the level speed.
      const speed = Math.hypot(ball.vx, ball.vy);
      const scale = ballSpeed(state.level) / speed;
      ball.vx *= scale;
      ball.vy *= scale;
      state.combo = 0; // touching the paddle resets the combo
    }
  }

  // Bricks: one swept pass. `hit` is the earliest face on the path.
  let hit = null;
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    const s = sweptBrickHit(prevX, prevY, ball.x, ball.y, brick, ball.r);
    if (s && (hit === null || s.t < hit.t)) hit = { brick, t: s.t, face: s.face };
  }

  if (hit && hit.t === 0) {
    // The step started inside a grown rectangle (grazing contact): resolve
    // positionally on the post-move overlap, with at most one bounce.
    let bounced = false;
    for (const brick of state.bricks) {
      if (!brick.alive || !collides(ball, brick)) continue;
      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
      if (!bounced) {
        bounceBall(ball, brick);
        bounced = true;
      }
    }
  } else if (hit) {
    // Kill every brick reached at the earliest time: a ball straddling a seam
    // between two bricks bounces once, not once per brick.
    const faces = new Set();
    for (const brick of state.bricks) {
      if (!brick.alive) continue;
      const s = sweptBrickHit(prevX, prevY, ball.x, ball.y, brick, ball.r);
      if (s && Math.abs(s.t - hit.t) < 1e-9) {
        brick.alive = false;
        state.combo += 1;
        state.score += scoreForBrick(brick, state.combo);
        faces.add(s.face);
      }
    }
    const b = hit.brick;
    if (faces.size > 1 || faces.has('corner')) {
      // Corner: both axes are inverted, the ball is pushed out diagonally.
      if (ball.x < b.x) ball.x = b.x - ball.r;
      else if (ball.x > b.x + b.w) ball.x = b.x + b.w + ball.r;
      if (ball.y < b.y) ball.y = b.y - ball.r;
      else if (ball.y > b.y + b.h) ball.y = b.y + b.h + ball.r;
      ball.vx = -ball.vx;
      ball.vy = -ball.vy;
    } else {
      const face = hit.face;
      if (face === 'left') {
        ball.x = b.x - ball.r;
        ball.vx = -Math.abs(ball.vx);
      } else if (face === 'right') {
        ball.x = b.x + b.w + ball.r;
        ball.vx = Math.abs(ball.vx);
      } else if (face === 'top') {
        ball.y = b.y - ball.r;
        ball.vy = -Math.abs(ball.vy);
      } else {
        ball.y = b.y + b.h + ball.r;
        ball.vy = Math.abs(ball.vy);
      }
    }
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}
