// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit. Face selection lives in `overlapFace` / `bounceBall`.
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// Face of a ball/brick overlap, from the axis of least penetration. Equal
// penetrations mean the ball sits on a corner: both axes are then inverted.
function overlapFace(ball, brick) {
  const penX = Math.min(ball.x + ball.r, brick.x + brick.w) - Math.max(ball.x - ball.r, brick.x);
  const penY = Math.min(ball.y + ball.r, brick.y + brick.h) - Math.max(ball.y - ball.r, brick.y);
  if (Math.abs(penX - penY) < 1e-6) return 'corner';
  if (penX < penY) return ball.x < brick.x ? 'left' : 'right';
  return ball.y < brick.y ? 'top' : 'bottom';
}

// Bounces the ball off one overlapping brick: flips the velocity component of
// the face hit (both on a corner) and pushes the ball back out of the
// rectangle, so it never sticks.
function bounceBall(ball, brick) {
  const face = overlapFace(ball, brick);
  if (face === 'corner') {
    if (ball.x < brick.x) ball.x = brick.x - ball.r;
    else if (ball.x > brick.x + brick.w) ball.x = brick.x + brick.w + ball.r;
    if (ball.y < brick.y) ball.y = brick.y - ball.r;
    else if (ball.y > brick.y + brick.h) ball.y = brick.y + brick.h + ball.r;
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
    return;
  }
  if (face === 'left') {
    ball.x = brick.x - ball.r;
    ball.vx = -Math.abs(ball.vx);
  } else if (face === 'right') {
    ball.x = brick.x + brick.w + ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (face === 'top') {
    ball.y = brick.y - ball.r;
    ball.vy = -Math.abs(ball.vy);
  } else {
    ball.y = brick.y + brick.h + ball.r;
    ball.vy = Math.abs(ball.vy);
  }
}

// Swept AABB test (slab method): does the ball's path segment from (x0, y0) to
// (x1, y1) cross the rectangle grown by `r`? Returns null, or { t, face } with
// t ∈ [0, 1]. t === 0 means the segment starts inside the grown rectangle: the
// caller then falls back to the positional test (`collides` + `bounceBall`).
function sweptBrickHit(x0, y0, x1, y1, brick, r) {
  const dx = x1 - x0;
  const dy = y1 - y0;
  const xl = brick.x - r;
  const xh = brick.x + brick.w + r;
  const yl = brick.y - r;
  const yh = brick.y + brick.h + r;

  let tx0, tx1;
  if (Math.abs(dx) < 1e-12) {
    if (x0 < xl || x0 > xh) return null;
    tx0 = -Infinity;
    tx1 = Infinity;
  } else {
    tx0 = (xl - x0) / dx;
    tx1 = (xh - x0) / dx;
    if (tx0 > tx1) {
      const t = tx0;
      tx0 = tx1;
      tx1 = t;
    }
  }

  let ty0, ty1;
  if (Math.abs(dy) < 1e-12) {
    if (y0 < yl || y0 > yh) return null;
    ty0 = -Infinity;
    ty1 = Infinity;
  } else {
    ty0 = (yl - y0) / dy;
    ty1 = (yh - y0) / dy;
    if (ty0 > ty1) {
      const t = ty0;
      ty0 = ty1;
      ty1 = t;
    }
  }

  const tClose = Math.max(tx0, ty0);
  const tFar = Math.min(tx1, ty1);
  if (tClose > tFar || tFar < 0 || tClose > 1) return null;
  if (tClose <= 0) return { t: 0, face: null };

  const corner = tx0 !== -Infinity && ty0 !== -Infinity && Math.abs(tx0 - ty0) < 1e-9;
  let face;
  if (corner) face = 'corner';
  else if (tx0 > ty0) face = dx > 0 ? 'left' : 'right';
  else face = dy > 0 ? 'top' : 'bottom';
  return { t: tClose, face };
}

